-- VE School Readiness Portal: 28-school Odisha baseline
-- Run after 01_schema.sql. Safe to rerun; existing rows are updated by ID.

on conflict (id) do update set
  name = excluded.name,
  district = excluded.district,
  grades = excluded.grades,
  current_engagement = excluded.current_engagement,
  metadata = excluded.metadata,
  active = true,
  updated_at = now();
